export type ParsedRecordMintedConditionInstruction<
  TProgram extends string = typeof KATHA_REGISTRY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    artwork: TAccountMetas[1];
    verification: TAccountMetas[2];
    head: TAccountMetas[3];
    report: TAccountMetas[4];
    custodyHead: TAccountMetas[5];
    asset: TAccountMetas[6];
    verifierAuthority: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: RecordMintedConditionInstructionData;
};

export function parseRecordMintedConditionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRecordMintedConditionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 9,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      artwork: getNextAccount(),
      verification: getNextAccount(),
      head: getNextAccount(),
      report: getNextAccount(),
      custodyHead: getNextAccount(),
      asset: getNextAccount(),
      verifierAuthority: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRecordMintedConditionInstructionDataDecoder().decode(instruction.data),
  };
}
